// 옛 TS(ADR-191 3단계 3e 이전)가 낸 값을 기대값으로 박은 벡터다. 기대값을 고치려면 옛 구현의 출력과 견주어 이유를 적는다.
// THROWS는 던져야 하는 입력이다. '의도한 차이:'로 시작하는 줄은 Rust가 옛 TS와 일부러 다르게 하는 것이다(거부 쪽으로만 다르다).
import { describe, expect, it } from 'vitest';
