import { describeDeclaredCheckChange, diffDeclaredChecks, hasDeclaredCheckChange, weakenedDeclarations, withDeclaredChecks } from './declared-checks';
import { describeLoadExpect, judgeLoad, loadRequestFor } from './load-check';

const THROWS: unknown = Symbol('throws');
const wf = (text: string): string => (text as unknown as { toWellFormed(): string }).toWellFormed();
const check = (fn: () => unknown, expected: unknown): void => {
  if (expected === THROWS) expect(fn).toThrow();
  else expect(fn()).toEqual(expected);
};
const redact = (text: string): string => text.split('S3CR3T').join('***');
const calls = (sink: string[]) => (text: string): string => {
  sink.push(text);
  return redact(text);
};

